sys_script_email.script:
(function runMailScript(
    current,
    template,
    email,
    email_action,
    event
) {

    /* =====================================================
       GET COLLECTION TOKEN
    ===================================================== */

    var token =
        current.getValue(
            'collection_toke0'
        );


    if (!token) {

        template.print(
            '<p>Collection QR is not yet available.</p>'
        );

        return;

    }


    /* =====================================================
       BUILD COLLECTION URL
    ===================================================== */

    var baseUrl =
        gs.getProperty(
            'glide.servlet.uri'
        );


    var collectionUrl =
    baseUrl +
    'campusmatch?id=campusmatch_collect&token=' +
    encodeURIComponent(
        token
    );


    /* =====================================================
       GENERATE QR IMAGE URL
    ===================================================== */

    var qrImageUrl =
        'https://api.qrserver.com/v1/create-qr-code/' +
        '?size=220x220' +
        '&data=' +
        encodeURIComponent(
            collectionUrl
        );


    /* =====================================================
       PRINT QR INTO EMAIL
    ===================================================== */

    template.print(
        '<div style="margin:24px 0;text-align:center;">'
    );


    template.print(
        '<p style="font-weight:700;">Collection QR</p>'
    );


    template.print(
        '<img src="' +
        qrImageUrl +
        '" width="220" height="220" ' +
        'alt="CampusMatch Collection QR" ' +
        'style="display:block;margin:0 auto;">'
    );


    template.print(
        '<p style="font-size:12px;color:#666;">' +
        'Show this QR to Security Desk staff when collecting the item.' +
        '</p>'
    );


    /* =====================================================
       FALLBACK LINK
    ===================================================== */

    template.print(
        '<p>' +
        '<a href="' +
        collectionUrl +
        '">' +
        'Open collection verification link' +
        '</a>' +
        '</p>'
    );


    template.print(
        '</div>'
    );

})(
    current,
    template,
    email,
    email_action,
    event
);
